-- Realistic relational questions over drug labels and disease descriptions, v2 (2026-10-13). drug.disease_name is a
-- list, so a drug treats a disease when the disease's name is one of the drug's listed diseases.
-- Q1: How many drugs of each form are prescription-only or over the counter?
SELECT CASE WHEN pharmaceutical_form LIKE '%tablet%' THEN 'tablet' WHEN pharmaceutical_form LIKE '%capsule%' THEN 'capsule' WHEN pharmaceutical_form LIKE '%injection%' THEN 'injection' ELSE 'other' END AS form, prescription_status, COUNT(*) AS drugs FROM drug GROUP BY form, prescription_status;
-- Q2: Per route of administration: how many drugs, and how many need a prescription?
SELECT CASE WHEN administration_route LIKE '%oral%' THEN 'oral' WHEN administration_route LIKE '%intravenous%' OR administration_route LIKE '%subcutaneous%' OR administration_route LIKE '%intramuscular%' THEN 'injected' WHEN administration_route LIKE '%topical%' THEN 'topical' WHEN administration_route LIKE '%inhal%' THEN 'inhaled' ELSE 'other' END AS route, COUNT(*) AS drugs, SUM(CASE WHEN prescription_status LIKE '%prescription%' THEN 1 ELSE 0 END) AS prescription_only FROM drug GROUP BY route;
-- Q3: Per form: how many drugs must be refrigerated, should be taken with food, or are unsuitable in pregnancy?
SELECT CASE WHEN pharmaceutical_form LIKE '%tablet%' THEN 'tablet' WHEN pharmaceutical_form LIKE '%capsule%' THEN 'capsule' WHEN pharmaceutical_form LIKE '%injection%' THEN 'injection' ELSE 'other' END AS form, SUM(CASE WHEN storage_conditions LIKE '%refrigerat%' THEN 1 ELSE 0 END) AS refrigerated, SUM(CASE WHEN recommended_usage LIKE '%with food%' THEN 1 ELSE 0 END) AS with_food, SUM(CASE WHEN unsuitable_population LIKE '%pregnan%' THEN 1 ELSE 0 END) AS not_in_pregnancy FROM drug GROUP BY form;
-- Q4: Per kind of disease: how many diseases, how many chronic, and how many treated with surgery?
SELECT CASE WHEN disease_type LIKE '%infectious%' THEN 'infectious' WHEN disease_type LIKE '%autoimmune%' THEN 'autoimmune' WHEN disease_type LIKE '%genetic%' THEN 'genetic' WHEN disease_type LIKE '%psychiatric%' THEN 'psychiatric' WHEN disease_type LIKE '%neoplastic%' THEN 'neoplastic' ELSE 'other' END AS kind, COUNT(*) AS diseases, SUM(CASE WHEN prognosis LIKE '%chronic%' THEN 1 ELSE 0 END) AS chronic, SUM(CASE WHEN treatments LIKE '%surgery%' THEN 1 ELSE 0 END) AS surgery FROM disease GROUP BY kind;
-- Q5: Per affected organ: how many diseases, and how many of them are chronic?
SELECT CASE WHEN affected_organs LIKE '%lung%' OR affected_organs LIKE '%respirat%' THEN 'lungs' WHEN affected_organs LIKE '%skin%' THEN 'skin' WHEN affected_organs LIKE '%heart%' OR affected_organs LIKE '%cardio%' THEN 'heart' WHEN affected_organs LIKE '%brain%' OR affected_organs LIKE '%nerv%' THEN 'nervous system' ELSE 'other' END AS organ, COUNT(*) AS diseases, SUM(CASE WHEN prognosis LIKE '%chronic%' THEN 1 ELSE 0 END) AS chronic FROM disease GROUP BY organ;
-- Q6: Per prognosis: how many diseases have a genetic risk factor, and how many can be prevented by vaccination?
SELECT CASE WHEN prognosis LIKE '%chronic%' THEN 'chronic' WHEN prognosis LIKE '%mortality%' THEN 'high mortality' WHEN prognosis LIKE '%recovery%' THEN 'recovery' ELSE 'other' END AS outlook, SUM(CASE WHEN risk_factors LIKE '%genetic%' THEN 1 ELSE 0 END) AS genetic_risk, SUM(CASE WHEN preventive_measures LIKE '%vaccin%' THEN 1 ELSE 0 END) AS vaccine_preventable FROM disease GROUP BY outlook;
-- Q7: Per main treatment: how many diseases list fever as a symptom?
SELECT CASE WHEN treatments LIKE '%surgery%' THEN 'surgery' WHEN treatments LIKE '%injection%' THEN 'injection' WHEN treatments LIKE '%oral%' THEN 'oral medication' ELSE 'other' END AS treatment, COUNT(*) AS diseases, SUM(CASE WHEN common_symptoms LIKE '%fever%' THEN 1 ELSE 0 END) AS with_fever FROM disease GROUP BY treatment;
-- Q8: Per kind of disease: how many drugs treat it, and how many of those need a prescription?
SELECT CASE WHEN disease.disease_type LIKE '%infectious%' THEN 'infectious' WHEN disease.disease_type LIKE '%autoimmune%' THEN 'autoimmune' WHEN disease.disease_type LIKE '%psychiatric%' THEN 'psychiatric' WHEN disease.disease_type LIKE '%neoplastic%' THEN 'neoplastic' ELSE 'other' END AS kind, COUNT(*) AS drugs, SUM(CASE WHEN drug.prescription_status LIKE '%prescription%' THEN 1 ELSE 0 END) AS prescription_only FROM drug JOIN disease ON '||' || REPLACE(drug.disease_name, ' || ', '||') || '||' LIKE '%||' || disease.disease_name || '||%' GROUP BY kind;
-- Q9: Which diseases have at least two drugs, most drugs first?
SELECT disease.disease_name, COUNT(*) AS drugs FROM drug JOIN disease ON '||' || REPLACE(drug.disease_name, ' || ', '||') || '||' LIKE '%||' || disease.disease_name || '||%' GROUP BY disease.disease_name HAVING COUNT(*) >= 2 ORDER BY drugs DESC;
-- Q10: How many different diseases do prescription-only and over-the-counter drugs treat?
SELECT drug.prescription_status, COUNT(DISTINCT disease.disease_name) AS diseases_treated FROM drug JOIN disease ON '||' || REPLACE(drug.disease_name, ' || ', '||') || '||' LIKE '%||' || disease.disease_name || '||%' GROUP BY drug.prescription_status;
-- Q11: Per disease prognosis: how many oral drugs are available?
SELECT CASE WHEN disease.prognosis LIKE '%chronic%' THEN 'chronic' WHEN disease.prognosis LIKE '%mortality%' THEN 'high mortality' ELSE 'other' END AS outlook, SUM(CASE WHEN drug.administration_route LIKE '%oral%' THEN 1 ELSE 0 END) AS oral_drugs, COUNT(*) AS drugs FROM drug JOIN disease ON '||' || REPLACE(drug.disease_name, ' || ', '||') || '||' LIKE '%||' || disease.disease_name || '||%' GROUP BY outlook;
-- Q12: Per drug form: how many drugs treat infectious diseases and how many treat other diseases?
SELECT CASE WHEN drug.pharmaceutical_form LIKE '%tablet%' THEN 'tablet' WHEN drug.pharmaceutical_form LIKE '%injection%' THEN 'injection' ELSE 'other' END AS form, SUM(CASE WHEN disease.disease_type LIKE '%infectious%' THEN 1 ELSE 0 END) AS for_infections, SUM(CASE WHEN disease.disease_type LIKE '%infectious%' THEN 0 ELSE 1 END) AS for_other FROM drug JOIN disease ON '||' || REPLACE(drug.disease_name, ' || ', '||') || '||' LIKE '%||' || disease.disease_name || '||%' GROUP BY form;
-- Q13: Which manufacturers make the most drugs?
SELECT manufacturer, COUNT(*) AS drugs FROM drug WHERE manufacturer IS NOT NULL GROUP BY manufacturer ORDER BY drugs DESC LIMIT 5;
-- Q14: How many drugs taken once, twice or three times a day need a prescription?
SELECT CASE WHEN dosage_frequency LIKE '%once daily%' OR dosage_frequency LIKE '%once a day%' THEN 'once a day' WHEN dosage_frequency LIKE '%twice%' THEN 'twice a day' WHEN dosage_frequency LIKE '%three times%' THEN 'three times a day' ELSE 'other' END AS frequency, prescription_status, COUNT(*) AS drugs FROM drug GROUP BY frequency, prescription_status;
-- Q15: Per kind of disease: how many are diagnosed by imaging and how many by laboratory tests?
SELECT CASE WHEN disease_type LIKE '%infectious%' THEN 'infectious' WHEN disease_type LIKE '%neoplastic%' THEN 'neoplastic' WHEN disease_type LIKE '%genetic%' THEN 'genetic' ELSE 'other' END AS kind, SUM(CASE WHEN diagnostic_methods LIKE '%imaging%' THEN 1 ELSE 0 END) AS by_imaging, SUM(CASE WHEN diagnostic_methods LIKE '%laborat%' THEN 1 ELSE 0 END) AS by_lab_test FROM disease GROUP BY kind;
-- Q16: How many drugs must be refrigerated?
SELECT COUNT(*) AS drugs FROM drug WHERE storage_conditions LIKE '%refrigerat%';
